# Counts US & Canada centers per megaregion (America 2050 megaregions, with the Great Lakes one taking in Toronto, Ottawa and Montreal; regions cross the border as one), approximated as distance from anchor cities.
import csv, math, collections
R = {  # region: [(lat, lon, radius km), ...]
 'Northeast (Boston–Washington)': [(42.36,-71.06,90),(41.82,-71.41,50),(41.76,-72.68,60),(41.31,-72.92,50),(40.71,-74.0,85),(40.22,-74.76,50),(39.95,-75.17,70),(40.6,-75.47,40),(40.27,-76.88,40),(39.74,-75.55,35),(39.29,-76.61,55),(38.9,-77.04,65),(42.65,-73.75,45),(43.0,-71.46,50),(43.66,-70.26,40),(41.5,-74.0,45)],
 'Great Lakes': [(41.88,-87.63,90),(42.33,-83.05,75),(41.5,-81.69,70),(41.08,-81.52,30),(39.96,-83.0,60),(39.1,-84.51,60),(39.76,-86.16,60),(43.04,-87.91,55),(43.07,-89.4,35),(44.98,-93.27,60),(40.44,-80.0,60),(42.89,-78.88,50),(43.16,-77.61,45),(43.05,-76.15,40),(38.25,-85.76,45),(38.63,-90.2,60),(41.66,-83.56,40),(42.96,-85.67,45),(42.73,-84.55,35),(39.76,-84.19,40),(41.08,-85.14,30),(41.68,-86.25,30),(41.59,-93.62,35),(42.27,-83.74,25),
 (43.65,-79.38,90),(45.42,-75.7,50),(45.5,-73.57,60),(46.81,-71.21,35),(43.26,-79.87,35),(42.98,-81.25,35),(43.45,-80.49,35),(42.31,-83.04,30),(44.23,-76.49,30)],
 'Piedmont Atlantic': [(33.75,-84.39,90),(35.23,-80.84,70),(35.78,-78.64,60),(36.07,-79.79,50),(36.1,-80.24,30),(34.85,-82.4,45),(34.0,-81.03,40),(36.16,-86.78,60),(35.05,-85.31,40),(35.96,-83.92,45),(33.52,-86.81,50),(34.73,-86.59,40)],
 'Florida': [(25.76,-80.19,110),(26.71,-80.05,50),(28.54,-81.38,80),(27.95,-82.46,80),(27.34,-82.53,50),(30.33,-81.66,50),(29.65,-82.32,30),(26.64,-81.87,55),(28.08,-80.61,40),(29.21,-81.02,40),(30.44,-84.28,30)],
 'Texas Triangle': [(32.78,-96.8,90),(29.76,-95.37,90),(30.27,-97.74,60),(29.42,-98.49,60),(31.55,-97.15,30)],
 'Gulf Coast': [(29.95,-90.07,70),(30.45,-91.19,40),(30.69,-88.04,45),(30.42,-87.22,40),(30.4,-88.89,40),(30.23,-92.02,30),(30.08,-94.1,30)],
 'Front Range': [(39.74,-104.99,80),(38.83,-104.82,40),(40.59,-105.08,40),(35.08,-106.65,50),(35.69,-105.94,35),(41.14,-104.82,25)],
 'Arizona Sun Corridor': [(33.45,-112.07,80),(32.22,-110.97,50)],
 'Southern California': [(34.05,-118.24,110),(32.72,-117.16,70),(33.83,-116.55,50),(34.42,-119.7,40),(36.17,-115.14,50),(34.11,-117.29,50)],
 'Northern California': [(37.77,-122.42,90),(37.34,-121.89,40),(38.58,-121.49,60),(36.74,-119.79,40),(36.97,-122.03,30),(36.6,-121.89,30),(39.53,-119.81,40),(38.44,-122.71,40)],
 'Cascadia': [(47.61,-122.33,90),(45.52,-122.68,70),(49.28,-123.12,70),(48.43,-123.37,40),(44.05,-123.09,40),(44.94,-123.04,30)],
}
def km(a, b, c, d):
    a, b, c, d = map(math.radians, (a, b, c, d))
    return 6371 * 2 * math.asin(math.sqrt(math.sin((c-a)/2)**2 + math.cos(a)*math.cos(c)*math.sin((d-b)/2)**2))
rows = list(csv.DictReader(open('exports/us-canada-centers-shluchim.csv')))
tot, out = collections.Counter(), collections.Counter()
for r in rows:
    la, lo = float(r['Latitude']), float(r['Longitude'])
    best = min(((km(la, lo, a, b) / rad, reg) for reg, pts in R.items() for a, b, rad in pts), default=(9, ''))
    reg = best[1] if best[0] <= 1 else 'Outside the megaregions'
    tot[reg] += 1; out[reg] += r['Outreach?'] == 'Outreach'
for reg, n in sorted(tot.items(), key=lambda x: -x[1]): print(f'{reg}|{n}|{out[reg]}')
print(f'Total|{sum(tot.values())}|{sum(out.values())}')
